local Private = select(2, ...)

function Private:ImportElvUI()
    local ProfileStrings = {
        ["PROFILE"] = "!E2!",
        ["PRIVATE"] = "!E2!",
    }

    return ProfileStrings
end


function Private:ImportSkironCooldownManager()
    local ProfileString = "!SCM:1:0!"

    return ProfileString
end

function Private:ImportPlatynator()
    local ProfileString = "PLATY!1!"

    return ProfileString
end

function Private:ImportBaganator()
    local ProfileString = "BGR!1!"

    return ProfileString
